java('ingest','IngestionSafetyTest',r'''import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
class IngestionSafetyTest {
 @TempDir Path dir;
 ContentAddressedStore cas()throws IOException{return new ContentAddressedStore(dir.resolve("cas"));}
 SafeSourceReader reader(SafeSourceReader.Limits limits)throws IOException{Files.createDirectories(dir.resolve("source"));return new SafeSourceReader(dir.resolve("source"),limits,cas());}
 @Test void canonicalPathsRejectTraversalAndWindowsAndAmbiguity(){for(String p:List.of("../a","/a","a/../b","a/./b","a//b","C:x","a\\b","","a\0b"))assertThrows(IllegalArgumentException.class,()->SnapshotManifest.normalize(p),p);assertEquals("src/é.java",SnapshotManifest.normalize("src/é.java"));}
 @Test void strictUtf8AndBoundedFilesAndCancellation()throws Exception{var reader=reader(new SafeSourceReader.Limits(16,32,2,100));Path file=dir.resolve("source/A.java");Files.write(file,new byte[]{(byte)0xc3,0x28});assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->false));Files.writeString(file,"a".repeat(17));assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->false));Files.writeString(file,"valid");assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->true));}
 @Test void configuredRootsAndSymlinksCannotEscape()throws Exception{var reader=reader(SafeSourceReader.Limits.defaults());Files.writeString(dir.resolve("outside"),"secret");assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("../"),false,Set.of(),()->false));Files.createSymbolicLink(dir.resolve("source/link"),dir.resolve("outside"));assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->false));assertThrows(IOException.class,()->reader.archive("t","r","1",Path.of("link"),()->false));}
 void zip(Path file,String name,String text)throws IOException{try(var zip=new ZipOutputStream(Files.newOutputStream(file))){zip.putNextEntry(new ZipEntry(name));zip.write(text.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}
 @Test void archivesRejectPathEscapeExpansionAndEntryQuotas()throws Exception{var reader=reader(new SafeSourceReader.Limits(10000,20000,2,2));Path z=dir.resolve("source/input.zip");zip(z,"../escape","x");assertThrows(IOException.class,()->reader.archive("t","r","1",Path.of("input.zip"),()->false));zip(z,"A.java","a".repeat(9000));assertThrows(IOException.class,()->reader.archive("t","r","1",Path.of("input.zip"),()->false));zip(z,"A.java","public class A {}");var m=reader.archive("t","r","1",Path.of("input.zip"),()->false);assertEquals(1,m.entries().size());assertFalse(m.complete());assertEquals("public class A {}",cas().text(m.entries().getFirst().sha256()));}
 @Test void documentAndAggregateQuotasFailExplicitly()throws Exception{var reader=reader(new SafeSourceReader.Limits(16,20,2,100));Files.writeString(dir.resolve("source/a"),"a".repeat(11));Files.writeString(dir.resolve("source/b"),"b".repeat(11));assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->false));Files.writeString(dir.resolve("source/a"),"a");Files.writeString(dir.resolve("source/b"),"b");Files.writeString(dir.resolve("source/c"),"c");assertThrows(IOException.class,()->reader.directory("t","r","1",Path.of("."),false,Set.of(),()->false));}
 @Test void contentAddressingVerifiesExistingObjectsAndDigestPaths()throws Exception{var c=cas();String hash=c.put("α UTF8".getBytes(StandardCharsets.UTF_8));assertEquals(hash,c.put("α UTF8".getBytes(StandardCharsets.UTF_8)));assertEquals("α UTF8",c.text(hash));Files.writeString(dir.resolve("cas").resolve(hash),"tampered");assertThrows(IOException.class,()->c.read(hash));assertThrows(IOException.class,()->c.read("../x"));assertThrows(IOException.class,()->c.put("α UTF8".getBytes(StandardCharsets.UTF_8)));}
 @Test void immutableManifestRoundtripIdempotencyAndConflicts()throws Exception{var e=new SnapshotManifest.Entry("src/A.java",Digests.sha256("a"),"java","source",List.of("fooBar"),"g:a","1");var m=new SnapshotManifest("t","r","rev",true,List.of(e),Set.of("old.java"));assertArrayEquals(m.bytes(),SnapshotManifest.read(m.bytes()).bytes());var jobs=new IngestionJob(dir.resolve("jobs"));var first=jobs.register("key",m);assertEquals(first,jobs.register("key",m));assertEquals(m,jobs.get(first.id()).manifest());assertThrows(IngestionJob.Conflict.class,()->jobs.register("key",new SnapshotManifest("t","r","rev2",true,List.of(e),Set.of("old.java"))));assertThrows(IllegalArgumentException.class,()->new SnapshotManifest("t","r","x",false,List.of(e,e),Set.of()));assertThrows(IllegalArgumentException.class,()->new SnapshotManifest("t","r","x",false,List.of(e),Set.of(e.path())));assertThrows(IllegalArgumentException.class,()->jobs.register("",m));}
 @Test void corruptMetadataAndCheckpointsAreNotTrusted()throws Exception{var cp=new CheckpointStore(dir.resolve("cp"));String hash=Digests.sha256("manifest");assertTrue(cp.read(hash).isEmpty());cp.save(hash,7);assertEquals(7,cp.read(hash).orElseThrow());Files.writeString(dir.resolve("cp").resolve(hash),"bad");assertThrows(IOException.class,()->cp.read(hash));assertThrows(IllegalArgumentException.class,()->cp.save(hash,-1));assertThrows(IOException.class,()->SnapshotManifest.read(new byte[]{1,2}));byte[] bad=new SnapshotManifest("t","r","x",false,List.of(),Set.of()).bytes();bad[3]=2;assertThrows(IOException.class,()->SnapshotManifest.read(bad));}
}
''',True)
java('index','GenerationLifecycleTest',r'''import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.apache.lucene.search.*;
class GenerationLifecycleTest {
 @TempDir Path root;
 SnapshotManifest manifest(ContentAddressedStore cas,String revision,int count)throws IOException {List<SnapshotManifest.Entry> entries=new ArrayList<>();for(int i=0;i<count;i++){String text="public void method"+i+"() {} revision "+revision;entries.add(new SnapshotManifest.Entry("src/A"+i+".java",cas.put(text.getBytes(StandardCharsets.UTF_8)),"java","source",List.of("method"+i),"g:a","1"));}return new SnapshotManifest("t","r",revision,false,entries,Set.of());}
 @Test void committedGenerationsHaveAtomicSnapshotAndLeaseLifetime()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var builder=new GenerationBuilder(index,cas);try(var publisher=new GenerationPublisher(index)){var one=builder.build(manifest(cas,"one",4),List.of(),GenerationBuilder.Fault.none(),()->false);publisher.publish(one,GenerationBuilder.Fault.none());GenerationLease old=publisher.acquire();assertEquals(4,old.searcher().count(new MatchAllDocsQuery()));var two=builder.build(manifest(cas,"two",6),publisher.sources(),GenerationBuilder.Fault.none(),()->false);publisher.publish(two,GenerationBuilder.Fault.none());assertEquals(one.id(),old.id());assertEquals(4,old.reader().numDocs());try(var lease=publisher.acquire()){assertEquals(two.id(),lease.id());assertEquals(6,lease.reader().numDocs());}assertThrows(GenerationPublisher.RetiredGeneration.class,()->publisher.acquire(one.id()));old.close();old.close();assertThrows(IllegalStateException.class,old::searcher);}try(var recovered=new GenerationPublisher(index);var lease=recovered.acquire()){assertEquals(6,lease.reader().numDocs());assertEquals("two",recovered.sources().getFirst().revision());}}
 @Test void explicitDeletionsAndPartialUploadsRespectSnapshotContract()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var builder=new GenerationBuilder(index,cas);try(var publisher=new GenerationPublisher(index)){var m=manifest(cas,"one",3);publisher.publish(builder.build(m,List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());var partial=new SnapshotManifest("t","r","partial",false,List.of(m.entries().getFirst()),Set.of());publisher.publish(builder.build(partial,publisher.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());assertEquals(3,publisher.sources().size());var invalid=new SnapshotManifest("t","r","full",true,List.of(m.entries().getFirst()),Set.of());assertThrows(IOException.class,()->builder.build(invalid,publisher.sources(),GenerationBuilder.Fault.none(),()->false));var full=new SnapshotManifest("t","r","full",true,List.of(m.entries().getFirst()),Set.of("src/A1.java","src/A2.java"));publisher.publish(builder.build(full,publisher.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());assertEquals(1,publisher.sources().size());}}
 @Test void hundredSeededFailureSchedulesNeverExposeMixedGenerations()throws Exception{Random random=new Random(7007);var boundaries=GenerationBuilder.Boundary.values();for(int schedule=0;schedule<100;schedule++){Path run=root.resolve("schedule-"+schedule);var cas=new ContentAddressedStore(run.resolve("cas"));Path index=run.resolve("index");var builder=new GenerationBuilder(index,cas);var chosen=boundaries[random.nextInt(boundaries.length)];try(var publisher=new GenerationPublisher(index)){publisher.publish(builder.build(manifest(cas,"old",3),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());GenerationBuilder.Fault failure=at->{if(at==chosen)throw new IOException("seeded failure "+at);};try{publisher.publish(builder.build(manifest(cas,"new",5),publisher.sources(),failure,()->false),failure);}catch(IOException expected){assertTrue(expected.getMessage().contains("seeded failure"));}}try(var recovered=new GenerationPublisher(index);var lease=recovered.acquire()){int n=lease.reader().numDocs();assertTrue(n==3||n==5,"schedule "+schedule);Set<String> revisions=new HashSet<>();recovered.sources().forEach(d->revisions.add(d.revision()));assertEquals(Set.of(n==3?"old":"new"),revisions,"schedule "+schedule);}}}
 @Test void corruptCurrentPointerFallsBackAndStagingIsQuarantined()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var b=new GenerationBuilder(index,cas);String previous;try(var p=new GenerationPublisher(index)){p.publish(b.build(manifest(cas,"old",2),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());previous=p.currentId();p.publish(b.build(manifest(cas,"new",3),p.sources(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());}Files.writeString(index.resolve("CURRENT"),"corrupt");Files.createDirectory(index.resolve("staging/incomplete"));Files.writeString(index.resolve("staging/incomplete/corrupt"),"metadata");try(var p=new GenerationPublisher(index)){assertEquals(previous,p.currentId());assertEquals(2,p.sources().size());}try(var files=Files.list(index.resolve("quarantine"))){assertEquals(2,files.count());}}
 @Test void cancellationAndSimulatedEnospcPreserveLastCommittedReader()throws Exception{var cas=new ContentAddressedStore(root.resolve("cas"));Path index=root.resolve("index");var b=new GenerationBuilder(index,cas);try(var p=new GenerationPublisher(index)){p.publish(b.build(manifest(cas,"old",2),List.of(),GenerationBuilder.Fault.none(),()->false),GenerationBuilder.Fault.none());String old=p.currentId();assertThrows(IOException.class,()->b.build(manifest(cas,"cancel",3),p.sources(),GenerationBuilder.Fault.none(),()->true));assertThrows(IOException.class,()->p.publish(b.build(manifest(cas,"disk",3),p.sources(),GenerationBuilder.Fault.none(),()->false),at->{if(at==GenerationBuilder.Boundary.BEFORE_POINTER)throw new FileSystemException(index.toString(),null,"No space left on device (injected ENOSPC)");}));assertEquals(old,p.currentId());assertEquals(2,p.sources().size());}}
 @Test void identifierTokenizerPreservesOriginalAndOffsetsWithUnicode()throws Exception{var parts=CodeIdentifierAnalyzer.parts("HTTPServer snake_case caféValue");assertTrue(parts.stream().anyMatch(p->p.term().equals("httpserver")&&p.start()==0&&p.end()==10));assertTrue(parts.stream().anyMatch(p->p.term().equals("http")));assertTrue(parts.stream().anyMatch(p->p.term().equals("server")));assertTrue(parts.stream().anyMatch(p->p.term().equals("snake")));assertTrue(parts.stream().anyMatch(p->p.term().equals("case")));assertTrue(parts.stream().anyMatch(p->p.term().equals("café")));try(var analyzer=new CodeIdentifierAnalyzer();var tokens=analyzer.tokenStream("content","fooBar")){var term=tokens.addAttribute(org.apache.lucene.analysis.tokenattributes.CharTermAttribute.class);var position=tokens.addAttribute(org.apache.lucene.analysis.tokenattributes.PositionIncrementAttribute.class);tokens.reset();List<String> values=new ArrayList<>();while(tokens.incrementToken()){values.add(term.toString());assertTrue(position.getPositionIncrement()>=0);}tokens.end();assertEquals(List.of("foobar","foo","bar"),values);}}
}
''',True)
java('query','SearchSecurityTest',r'''import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
class SearchSecurityTest {
 @TempDir Path root;
 SnapshotManifest manifest(SearchEngine e,String tenant,String repo,int count,String word)throws IOException{List<SnapshotManifest.Entry> entries=new ArrayList<>();for(int i=0;i<count;i++){String content="public void "+word+i+"() {} shared phrase engine";entries.add(new SnapshotManifest.Entry("src/"+word+i+".java",e.contentStore().put(content.getBytes(StandardCharsets.UTF_8)),"java","source",List.of(word+i),"g:a","1"));}return new SnapshotManifest(tenant,repo,"v1",false,entries,Set.of());}
 @Test void isolationCoversResultsCountsFacetsSuggestionsExplanationsCursorsAndRepeatedQueries()throws Exception{AuthorizationFilter auth=new AuthorizationFilter();var owner=auth.update("owner","tenant1",Set.of("public","denied"),true);var alice=auth.update("alice","tenant1",Set.of("public"),false);var bob=auth.update("bob","tenant2",Set.of("public"),false);try(var e=new SearchEngine(root,auth)){e.ingest(owner,"1",manifest(e,"tenant1","public",5,"visible"),GenerationBuilder.Fault.none(),()->false);e.ingest(owner,"2",manifest(e,"tenant1","denied",4,"topSecret"),GenerationBuilder.Fault.none(),()->false);e.ingest(bob,"3",manifest(e,"tenant2","public",3,"foreignSecret"),GenerationBuilder.Fault.none(),()->false);SearchEngine.Request request=new SearchEngine.Request("shared",2,null,Map.of());for(int run=0;run<3;run++){var r=e.search("alice",request);assertEquals(5,r.totalHits());assertEquals(Map.of("public",5),r.facets());assertFalse(r.toString().contains("topSecret"));assertFalse(r.toString().contains("foreignSecret"));assertNotNull(r.cursor());assertEquals(2,r.results().size());assertThrows(IllegalArgumentException.class,()->e.search("bob",new SearchEngine.Request("shared",2,r.cursor(),Map.of())));var next=e.search("alice",new SearchEngine.Request("shared",2,r.cursor(),Map.of()));assertNotEquals(r.results().getFirst().key(),next.results().getFirst().key());assertThrows(IllegalArgumentException.class,()->e.search("alice",new SearchEngine.Request("phrase",2,r.cursor(),Map.of())));assertEquals(List.of(),e.suggest("alice","topSecret"));assertEquals(5,e.suggest("alice","visible").size());}assertEquals(0,e.search("alice",new SearchEngine.Request("repository:denied",10,null,Map.of())).totalHits());assertEquals(0,e.search("alice",new SearchEngine.Request("shared",10,null,Map.of("repository","denied"))).totalHits());var cursor=e.search("alice",request).cursor();auth.update("alice","tenant1",Set.of(),false);assertThrows(IllegalArgumentException.class,()->e.search("alice",new SearchEngine.Request("shared",2,cursor,Map.of())));assertEquals(0,e.search("alice",request).totalHits());assertThrows(SecurityException.class,()->e.ingest(alice,"denied",manifest(e,"tenant1","denied",1,"x"),GenerationBuilder.Fault.none(),()->false));assertTrue(Files.isDirectory(root.resolve("index/tenant1")));assertTrue(Files.isDirectory(root.resolve("index/tenant2")));}}
 @Test void tenThousandIdenticalRecordsYieldOneLogicalCopyPerKey()throws Exception{var auth=new AuthorizationFilter();var a=auth.update("a","t",Set.of("r"),true);try(var e=new SearchEngine(root,auth)){var m=manifest(e,"t","r",10000,"method");var first=e.ingest(a,"same",m,GenerationBuilder.Fault.none(),()->false);String generation=e.generations("t").currentId();assertEquals(first,e.ingest(a,"same",m,GenerationBuilder.Fault.none(),()->false));assertEquals(generation,e.generations("t").currentId());assertEquals(10000,e.search("a",new SearchEngine.Request("shared",10,null,Map.of())).totalHits());assertEquals(10000,e.generations("t").sources().size());assertTrue(e.completed(first.id()));assertEquals(first,e.job(a,first.id()));assertThrows(IngestionJob.Conflict.class,()->e.ingest(a,"same",new SnapshotManifest("t","r","changed",false,m.entries(),Set.of()),GenerationBuilder.Fault.none(),()->false));}}
 @Test void parserBoundsBooleanPhraseAndTypedFieldsAreReal()throws Exception{var auth=new AuthorizationFilter();var a=auth.update("a","t",Set.of("r"),true);try(var e=new SearchEngine(root,auth)){e.ingest(a,"1",manifest(e,"t","r",3,"fooBar"),GenerationBuilder.Fault.none(),()->false);assertEquals(3,e.search("a",new SearchEngine.Request("\"shared phrase\" AND language:java NOT kind:artifact",10,null,Map.of())).totalHits());assertEquals(3,e.search("a",new SearchEngine.Request("fooBar0 OR fooBar1 OR fooBar2",10,null,Map.of())).totalHits());assertEquals(0,e.search("a",new SearchEngine.Request("\"phrase shared\"",10,null,Map.of())).totalHits());}for(String q:List.of("","a*","unknown:x","\"unclosed","a AND","a OR",":","(a","a)","(".repeat(10)+"a"+")".repeat(10),"a ".repeat(65),"x".repeat(513)))assertThrows(IllegalArgumentException.class,()->QueryAst.parse(q),q);assertThrows(IllegalArgumentException.class,()->new SearchEngine.Request("x",101,null,Map.of()));assertThrows(IllegalArgumentException.class,()->new SearchEngine.Request("x",0,null,Map.of()));assertThrows(IllegalArgumentException.class,()->new SearchEngine.Request("x",1,null,Map.of("unsafe","x")));}
 @Test void cursorsRequireSignaturePrincipalPermissionQueryAndTime(){byte[] key=new byte[32];Arrays.fill(key,(byte)4);Clock clock=Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC);var a=new AuthorizationFilter.Access("a","t",Set.of("r"),1,false);var codec=new SearchCursor(key,clock);String gen="11111111-1111-1111-1111-111111111111";String c=codec.encode(a,"digest",gen,20);assertEquals(new SearchCursor.Position(gen,20),codec.decode(c,a,"digest"));assertThrows(IllegalArgumentException.class,()->codec.decode(c+"x",a,"digest"));assertThrows(IllegalArgumentException.class,()->codec.decode(c,a,"other"));assertThrows(IllegalArgumentException.class,()->codec.decode(c,new AuthorizationFilter.Access("b","t",Set.of("r"),1,false),"digest"));var expired=new SearchCursor(key,Clock.offset(clock,Duration.ofMinutes(6)));assertThrows(IllegalArgumentException.class,()->expired.decode(c,a,"digest"));assertThrows(IllegalArgumentException.class,()->codec.decode("x".repeat(2049),a,"digest"));}
 @Test void retiredCursorCannotReadNewGeneration()throws Exception{var auth=new AuthorizationFilter();var a=auth.update("a","t",Set.of("r"),true);try(var e=new SearchEngine(root,auth)){e.ingest(a,"1",manifest(e,"t","r",3,"old"),GenerationBuilder.Fault.none(),()->false);var cursor=e.search("a",new SearchEngine.Request("shared",1,null,Map.of())).cursor();e.ingest(a,"2",manifest(e,"t","r",3,"new"),GenerationBuilder.Fault.none(),()->false);assertThrows(GenerationPublisher.RetiredGeneration.class,()->e.search("a",new SearchEngine.Request("shared",1,cursor,Map.of())));}}
}
''',True)
